-- 016 prepared; run only in an explicitly authorized isolated rehearsal.
begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions,pg_catalog;
select no_plan();
create temporary table pi_ids as select gen_random_uuid() admin,gen_random_uuid() person,gen_random_uuid() shop_a,gen_random_uuid() shop_b,gen_random_uuid() invite;
insert into auth.users(id,email,is_anonymous,email_confirmed_at) select admin,'pi-admin@example.invalid',false,now() from pi_ids union all select person,'pi-person@example.invalid',false,now() from pi_ids;
insert into profiles(id,display_name) select admin,'Admin' from pi_ids union all select person,'Account person' from pi_ids;
insert into barbershops(id,name) select shop_a,'Shop A' from pi_ids union all select shop_b,'Shop B' from pi_ids;
insert into barbershop_memberships(user_id,barbershop_id,role,status) select admin,shop_a,'administrator','active' from pi_ids;
insert into private.barbershop_ownership(barbershop_id,owner_user_id,created_by,source) select shop_a,admin,admin,'new-shop' from pi_ids;
insert into staff_invitations(id,barbershop_id,recipient_user_id,inviter_user_id) select invite,shop_a,person,admin from pi_ids;
select set_config('request.jwt.claim.sub',(select admin::text from pi_ids),true);
select set_config('request.jwt.claims',jsonb_build_object('sub',(select admin from pi_ids),'role','authenticated')::text,true);
grant select on pi_ids to authenticated;
set local role authenticated;
create temporary table pi_result as select public.remind_professional_invitation(shop_a,invite) data from pi_ids;
reset role;
select is(data->>'created','true','authorized administrator creates reminder') from pi_result;
select is(public.remind_professional_invitation(shop_a,invite)->>'created','false','immediate repeat is suppressed') from pi_ids;
select is((select count(*)::int from private.web_notifications where source_key like 'invitation-reminder:%'),1,'one reminder after repeated requests');
select is(public.list_shop_staff_invitations(shop_a)->0->>'recipientEmail','pi-person@example.invalid','admin reads real pending recipient email') from pi_ids;
select is((select status from staff_invitations where id=(select invite from pi_ids)),'pending','reminder does not replace or accept invitation');
select throws_ok(format('select public.remind_professional_invitation(%L,%L)',shop_b,invite),'42501','FORBIDDEN','wrong shop administrator denied') from pi_ids;
update staff_invitations set status='cancelled',responded_at=statement_timestamp() where id=(select invite from pi_ids);
select throws_ok(format('select public.remind_professional_invitation(%L,%L)',shop_a,invite),'P0002','NOT_AVAILABLE','resolved invitation cannot be reminded') from pi_ids;
select ok(public.list_shop_staff_invitations(shop_a)->0->>'recipientEmail' is null,'email not exposed on historical invitation') from pi_ids;
select set_config('request.jwt.claim.sub',(select person::text from pi_ids),true);
select set_config('request.jwt.claims',jsonb_build_object('sub',(select person from pi_ids),'role','authenticated')::text,true);
select throws_ok(format('select public.remind_professional_invitation(%L,%L)',shop_a,invite),'42501','FORBIDDEN','recipient cannot act as administrator') from pi_ids;
insert into barbershop_memberships(user_id,barbershop_id,role,status) select person,shop_a,'administrator','active' from pi_ids;
select throws_ok(format('select public.remind_professional_invitation(%L,%L)',shop_a,invite),'42501','FORBIDDEN','secondary administrator without team capability cannot resend') from pi_ids;
select ok(not(public.list_own_staff_invitations()->0 ? 'recipientEmail'),'own projection has no added emails');
select ok(exists(select 1 from jsonb_array_elements(public.list_my_notifications()->'items') n where n->>'title'='Invitación pendiente'),'recipient sees reminder in existing inbox');
select ok(not has_function_privilege('anon','public.remind_professional_invitation(uuid,uuid)','execute'),'anonymous has no reminder permission');
select * from finish();
rollback;
